private ApiResult doSeal(SealRequest req) {
    List<String> nos = req.sampleNos();
    if (nos == null || nos.isEmpty()) throw unprocessable("封存包至少包含 1 件样本");
    if (nos.size() > 20) throw unprocessable("封存包最多 20 件样本");
    if (new HashSet<>(nos).size() != nos.size()) throw unprocessable("请求内样本编号重复");
