    for (String no : nos) { query sample; if missing → 422 "样本未采集: "+no; if stratumId != stratum.id → 422 "跨层位混包"; }
    // create package
    KeyHolder kh; insert seal_package(package_no, lineage_no=package_no, version=1, stratum_id, seal_no, status='SEALED', prev_anomaly_id=null, created_at)
      catch DuplicateKeyException → 409 "封存包编号已存在"
    long pkgId = key;
    insert seal_event(pkgId, 'SEALED', sealNo, "操作员:"+operator, now)
