    stratum_id BIGINT NOT NULL COMMENT '所属层位ID，包内样本必须同属该层位',
    seal_no VARCHAR(64) NOT NULL COMMENT '封签编号，交接时锁定，不可删除',
    status VARCHAR(16) NOT NULL COMMENT '状态：SEALED已封存/HANDED_OVER已交接/SEAL_BROKEN封签破损',
