);
COMMENT ON TABLE seal_package IS '封存包：同一层位最多20件样本，重新封存生成新版本';

CREATE TABLE package_item (
    id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    package_id BIGINT NOT NULL COMMENT '封存包ID',
