@Service
public class SampleService {
    private final JdbcClient jdbc; private final Clock clock; private final StratumService strata; private final IdempotencyService idem;

    @Transactional
    public StoredResponse collect(CollectRequest req) {
        return idem.execute(req.requestId(), "COLLECT", req, () -> doCollect(req));
    }

    private ApiResult doCollect(CollectRequest req) {
        StratumRef stratum = strata.findByCode(req.siteCode(), req.stratumNo())
            .orElseThrow(() -> BizException.unprocessable("层位未登记: " + req.siteCode() + "/" + req.stratumNo()));
        Instant now = clock.instant();
        try {
            jdbc.sql("INSERT INTO sample(sample_no, stratum_id, grid_ref, collected_at, status) VALUES (?,?,?,?,'COLLECTED')")
                .params(req.sampleNo(), stratum.id(), req.gridRef(), Timestamp.from(now)).update();
        } catch (DuplicateKeyException e) {
            throw BizException.conflict("样本编号已存在（编号相同层位不同亦视为冲突）: " + req.sampleNo());
        }
        return ApiResult.created(new SampleResponse(req.sampleNo(), req.siteCode(), req.stratumNo(), req.gridRef(), now, "COLLECTED"));
    }
