private ApiResult doReseal(ResealRequest req) {
    PkgRow old = lockPackage(req.oldPackageNo());
    if (!"SEAL_BROKEN".equals(old.status())) throw BizException.unprocessable("仅封签破损的包可重新封存: " + req.oldPackageNo());
    Long anomalyId = jdbc.sql("SELECT id FROM seal_event WHERE package_id=? AND event_type='SEAL_BROKEN' ORDER BY id DESC LIMIT 1")
        .param(old.id()).query(Long.class).optional()
        .orElseThrow(() -> BizException.unprocessable("缺少封签异常记录: " + req.oldPackageNo()));
    Instant now = clock.instant();
    KeyHolder kh = new GeneratedKeyHolder();
    long newId;
    try {
        jdbc.sql("INSERT INTO seal_package(package_no, lineage_no, version, stratum_id, seal_no, status, prev_anomaly_id, created_at) VALUES (?,?,?,?,?,'SEALED',?,?)")
            .params(req.packageNo(), old.lineageNo(), old.version() + 1, old.stratumId(), req.sealNo(), anomalyId, Timestamp.from(now))
            .update(kh);
        newId = kh.getKey().longValue();
    } catch (DuplicateKeyException e) {
        throw BizException.conflict("封存包编号或版本冲突: " + req.packageNo());
    }
    jdbc.sql("INSERT INTO package_item(package_id, sample_id) SELECT ?, sample_id FROM package_item WHERE package_id=?")
        .params(newId, old.id()).update();
    int moved = jdbc.sql("UPDATE sample SET package_id=?, status='SEALED' WHERE package_id=?").params(newId, old.id()).update();
    insertEvent(newId, "RESEALED", req.sealNo(), "重新封存，引用异常#" + anomalyId + " 操作人:" + req.operator());
    return ApiResult.created(new PackageResponse(req.packageNo(), old.lineageNo(), old.version() + 1, req.sealNo(), "SEALED", moved, anomalyId));
}
