 */
class SealAnomalyTest extends BaseApiTest {

    @BeforeEach
    void seed() throws Exception {
        registerStratum("SITE-T", "L");
        collect("REQ-AN-S1", "A-01", "L", "G-01");
        collect("REQ-AN-S2", "A-02", "L", "G-02");
    }

